const staticData = $getWorkflowStaticData('global');
if (!staticData.alerted) staticData.alerted = {};

const sampleEvents = [
  {
    id: 'evt_sample_1',
    summary: 'AQI Pipeline Review',
    start: { dateTime: new Date(Date.now() + 14 * 60 * 1000).toISOString() },
    end: { dateTime: new Date(Date.now() + 74 * 60 * 1000).toISOString() },
    attendees: [{ email: 'nelson.torres@adquadrant.com' }, { email: 'vish@adquadrant.com' }],
    hangoutLink: 'https://meet.google.com/abc-defg-hij',
    status: 'confirmed'
  }
];

var events = $input.first().json.items || sampleEvents;
var now = new Date();
var alerts = [];

for (var i = 0; i < events.length; i++) {
  var evt = events[i];
  if (!evt.start || !evt.start.dateTime) continue;
  if (evt.status === 'declined') continue;
  var attendees = evt.attendees || [];
  var otherAttendees = attendees.filter(function(a) {
    return a.email !== 'nelson.torres@adquadrant.com';
  });
  if (attendees.length > 0 && otherAttendees.length === 0) continue;

  var startTime = new Date(evt.start.dateTime);
  var endTime = new Date(evt.end.dateTime);
  var minutesUntilStart = (startTime - now) / (1000 * 60);

  var attendeeNames = otherAttendees.map(function(a) {
    return a.displayName || a.email.split('@')[0];
  }).join(', ');
  var joinLink = evt.hangoutLink || evt.conferenceData?.entryPoints?.[0]?.uri || 'No link';

  var t15Key = 'calendar_alerted_' + evt.id + '_t15';
  if (minutesUntilStart >= 13 && minutesUntilStart <= 17 && !staticData.alerted[t15Key]) {
    staticData.alerted[t15Key] = new Date().toISOString();
    alerts.push({
      type: 't15',
      event_id: evt.id,
      title: evt.summary,
      start: startTime.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      end: endTime.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      attendees: attendeeNames,
      join_link: joinLink,
      message: 'In 15 min: ' + evt.summary + ' | ' + attendeeNames + ' | ' + joinLink
    });
  }

  var t1Key = 'calendar_alerted_' + evt.id + '_t1';
  if (minutesUntilStart >= 0 && minutesUntilStart <= 2 && !staticData.alerted[t1Key]) {
    staticData.alerted[t1Key] = new Date().toISOString();
    alerts.push({
      type: 't1',
      event_id: evt.id,
      title: evt.summary,
      join_link: joinLink,
      message: 'Starting now: ' + evt.summary + ' | ' + joinLink
    });
  }
}

var dayAgo = Date.now() - 24 * 60 * 60 * 1000;
for (var key in staticData.alerted) {
  if (new Date(staticData.alerted[key]).getTime() < dayAgo) {
    delete staticData.alerted[key];
  }
}

return [{ json: {
  has_alerts: alerts.length > 0,
  alert_count: alerts.length,
  alerts: alerts,
  events_checked: events.length
} }];
